const input = $input.first().json;

// Check if this is a thread reply (has messages array from HTTP request) or new message (webhook)
const isThread = input.messages && Array.isArray(input.messages);

if (isThread) {
  // Thread reply - full context from HTTP request
  const messages = input.messages;

  const latestUserMessage = messages
    .filter(msg => !msg.bot_id)
    .slice(-1)[0];

  const parentMessage = messages[0];

  const recentMessages = messages.slice(-4).map(msg => ({
    user: msg.bot_id ? 'RAG Bot' : `<@${msg.user}>`,
    user_id: msg.user,
    text: msg.text
  }));

  const userIds = [...new Set(messages
    .filter(msg => !msg.bot_id)
    .map(msg => msg.user))];

  return {
    latestMessage: latestUserMessage.text,
    latestMessageUserId: latestUserMessage.user,
    parentMessage: parentMessage.text,
    parentMessageUserId: parentMessage.user,
    threadContext: recentMessages,
    allUserIds: userIds,
    messageCount: messages.length
  };
} else {
  // New message in channel - from webhook
  const event = input.body?.event || input.event || input;

  return {
    latestMessage: event.text,
    latestMessageUserId: event.user,
    parentMessage: null,
    parentMessageUserId: null,
    threadContext: [],
    allUserIds: [event.user],
    messageCount: 1
  };
}

// Metadata-aware reranking after Pinecone cosine retrieval.
// Receives top-K matches, applies multiplicative boosts using metadata
// signals from slack-to-pc.py and articles-to-pc.py, returns the top N
// chunks as ONE ITEM (containing a chunks array) so the agent runs once.

// ─── Tunable weights ──────────────────────────────────────────────
const W_PRIMARY_TAG = 1.40; // :verified: tag = team-verified content
const W_TRUSTED_AUTHOR     = 1.30; // any reply from a TRUSTED_USERS SME
const W_MULTI_TRUSTED_AUTHOR   = 1.05; // 2+ SME-authored replies in same thread
const W_SYNTHETIC_SUMMARY       = 1.10; // Slack synth doc (clean Q+A pair)
const W_HAS_IMAGES  = 1.05; // helpcenter chunk with UI screenshots
const FINAL_TOP_K   = 10;   // results passed to the agent

// ─── Read incoming matches ────────────────────────────────────────
// Pinecone's n8n node may emit one item per match, or one item with a
// `matches` / `documents` array. Normalize.
const items = $input.all();
let matches;
if (items.length === 1 && Array.isArray(items[0].json.matches)) {
  matches = items[0].json.matches.map(m => ({ json: m }));
} else if (items.length === 1 && Array.isArray(items[0].json.documents)) {
  matches = items[0].json.documents.map(m => ({ json: m }));
} else {
  matches = items;
}

// ─── Apply boost ──────────────────────────────────────────────────
const boosted = matches.map((item, originalIdx) => {
  const d = item.json || {};
  const meta = d.metadata || {};
  const baseScore = typeof d.score === 'number' ? d.score : 0;

  let mult = 1.0;
  const reasons = [];

  if (meta.has_primary_tag) { mult *= W_PRIMARY_TAG; reasons.push(':verified:'); }
  if (meta.has_trusted)              { mult *= W_TRUSTED_AUTHOR;     reasons.push('trusted'); }
  if ((meta.trusted_count || 0) >= 2){ mult *= W_MULTI_TRUSTED_AUTHOR;   reasons.push('multi-SME'); }
  if (meta.doc_type === 'thread_synth') { mult *= W_SYNTHETIC_SUMMARY;    reasons.push('synth'); }
  if (meta.source === 'helpcenter' && meta.has_images) { mult *= W_HAS_IMAGES; reasons.push('images'); }

  // Resolve the chunk text — ingest scripts store it in metadata.text;
  // n8n's LangChain abstraction may also expose it as pageContent.
  const chunkText = meta.text || d.pageContent || d.text || '';

  return {
    metadata:         meta,
    chunk_text:       chunkText,
    base_score:       Math.round(baseScore * 10000) / 10000,
    boost_multiplier: Math.round(mult * 1000) / 1000,
    boosted_score:    baseScore * mult,
    boost_reasons:    reasons.join(', ') || 'none',
    original_rank:    originalIdx + 1,
  };
});

// ─── Sort, slice, annotate ────────────────────────────────────────
boosted.sort((a, b) => b.boosted_score - a.boosted_score);
const topResults = boosted.slice(0, FINAL_TOP_K).map((c, newIdx) => ({
  ...c,
  final_rank: newIdx + 1,
  rank_delta: c.original_rank - (newIdx + 1),
}));

// Return ONE item carrying the chunks as an array, so the agent runs
// exactly once with all chunks available via $('Metadata Boost').first().
return [{
  json: {
    chunks: topResults,
    chunk_count: topResults.length,
  }
}];
